from z3 import *
import itertools

n = 16

def get_edge(edge_dict, i, j):
    if i < j:
        return edge_dict[(i,j)]
    else:
        return edge_dict[(j,i)]

def solve_with_constraints(forbid_6cycles=False):
    edge = {}
    for i in range(n):
        for j in range(i+1, n):
            edge[(i,j)] = Bool(f"e_{i}_{j}")

    s = Solver()

    # At least 25 edges
    s.add(Sum([If(edge[(i,j)], 1, 0) for i in range(n) for j in range(i+1, n)]) >= 25)

    # No 3-cycles
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                s.add(Not(And(get_edge(edge,i,j), get_edge(edge,j,k), get_edge(edge,i,k))))

    # No 4-cycles
    for a in range(n):
        for b in range(a+1, n):
            for c in range(b+1, n):
                for d in range(c+1, n):
                    s.add(Not(And(get_edge(edge,a,b), get_edge(edge,b,c), get_edge(edge,c,d), get_edge(edge,a,d))))
                    s.add(Not(And(get_edge(edge,a,c), get_edge(edge,c,b), get_edge(edge,b,d), get_edge(edge,a,d))))
                    s.add(Not(And(get_edge(edge,a,b), get_edge(edge,b,d), get_edge(edge,d,c), get_edge(edge,a,c))))

    # No 5-cycles
    for a in range(n):
        for b in range(a+1, n):
            for c in range(b+1, n):
                for d in range(c+1, n):
                    for e in range(d+1, n):
                        verts = [a,b,c,d,e]
                        # Generate all 12 distinct 5-cycles
                        # A 5-cycle is a cyclic ordering; there are 5!/10 = 12 distinct ones
                        cycles = [
                            [0,1,2,3,4],
                            [0,1,2,4,3],
                            [0,1,3,2,4],
                            [0,1,3,4,2],
                            [0,1,4,2,3],
                            [0,1,4,3,2],
                            [0,2,1,3,4],
                            [0,2,1,4,3],
                            [0,2,3,1,4],
                            [0,2,4,1,3],
                            [0,3,1,2,4],
                            [0,3,2,1,4],
                        ]
                        for cyc in cycles:
                            s.add(Not(And(
                                get_edge(edge, verts[cyc[0]], verts[cyc[1]]),
                                get_edge(edge, verts[cyc[1]], verts[cyc[2]]),
                                get_edge(edge, verts[cyc[2]], verts[cyc[3]]),
                                get_edge(edge, verts[cyc[3]], verts[cyc[4]]),
                                get_edge(edge, verts[cyc[4]], verts[cyc[0]])
                            )))

    if forbid_6cycles:
        #encoding No 6-cycles
        for a in range(n):
            for b in range(a+1, n):
                for c in range(b+1, n):
                    for d in range(c+1, n):
                        for e in range(d+1, n):
                            for f in range(e+1, n):
                                verts = [a,b,c,d,e,f]
                                # All 60 distinct 6-cycles
                                # Generate all permutations of 6 elements that are distinct cycles
                                # 6! / (6*2) = 60
                                import itertools as it
                                count = 0
                                seen = set()
                                for perm in it.permutations(range(6)):
                                    # Canonicalize: rotate so 0 is first, then decide direction
                                    idx0 = perm.index(0)
                                    rotated = perm[idx0:] + perm[:idx0]
                                    if rotated[1] > rotated[-1]:
                                        rotated = (rotated[0],) + tuple(reversed(rotated[1:]))
                                    key = rotated
                                    if key not in seen:
                                        seen.add(key)
                                        s.add(Not(And(
                                            get_edge(edge, verts[rotated[0]], verts[rotated[1]]),
                                            get_edge(edge, verts[rotated[1]], verts[rotated[2]]),
                                            get_edge(edge, verts[rotated[2]], verts[rotated[3]]),
                                            get_edge(edge, verts[rotated[3]], verts[rotated[4]]),
                                            get_edge(edge, verts[rotated[4]], verts[rotated[5]]),
                                            get_edge(edge, verts[rotated[5]], verts[rotated[0]])
                                        )))

    print("Checking...")
    result = s.check()
    print("Result:", result)
    if result == sat:
        m = s.model()
        edges = []
        for i in range(n):
            for j in range(i+1, n):
                if is_true(m.evaluate(edge[(i,j)])):
                    edges.append((i,j))
        return edges
    return None

